/**
 * VaultStore — file-backed CRUD over an Obsidian vault.
 *
 * Layout:
 *   <root>/MEMORY.md            master index (generated by wiki.ts)
 *   <root>/topics/<slug>.md     durable topic pages
 *   <root>/daily/YYYY-MM-DD.md  append-only capture logs
 *
 * Every page carries a small YAML frontmatter block. Writes are atomic
 * (tmp + rename) and serialized per vault-relative path, so concurrent
 * sessions rebound to the same process cannot interleave writes to a page.
 */

import { mkdir, readFile, readdir, rename, rm, writeFile } from "node:fs/promises";
import { dirname, join, resolve, sep } from "node:path";

export interface PageMeta {
	title: string;
	created: string; // ISO timestamp
	updated: string; // ISO timestamp
	source?: string; // retain | tool | manual
	importance?: number; // 1..5
	tags?: string[];
}

export interface Page {
	/** Vault-relative posix path, e.g. "topics/omp-config.md". */
	path: string;
	meta: PageMeta;
	/** Markdown body after the frontmatter block. */
	body: string;
}

export function slugify(title: string): string {
	const slug = title
		.toLowerCase()
		.replace(/[^a-z0-9]+/g, "-")
		.replace(/^-+|-+$/g, "")
		.slice(0, 80);
	return slug || "untitled";
}

// ---------------------------------------------------------------------------
// Frontmatter codec — deliberately minimal: flat scalars plus string arrays.
// Strings serialize as JSON double-quoted scalars, which are valid YAML 1.2
// and parse correctly in Obsidian. Block-style arrays (`key:\n  - item`)
// produced by hand edits in Obsidian are accepted on read.
// ---------------------------------------------------------------------------

function serializeValue(value: string | number | string[]): string {
	if (Array.isArray(value)) return `[${value.map(v => JSON.stringify(v)).join(", ")}]`;
	if (typeof value === "number") return String(value);
	return JSON.stringify(value);
}

export function serializePage(meta: PageMeta, body: string): string {
	const keys = ["title", "created", "updated", "source", "importance", "tags"] as const;
	const lines = ["---"];
	for (const key of keys) {
		const value = meta[key];
		if (value === undefined) continue;
		lines.push(`${key}: ${serializeValue(value)}`);
	}
	lines.push("---", "");
	return `${lines.join("\n")}${body.replace(/^\n+/, "")}`;
}

/** Split an inline `[a, "b, c"]` list on top-level commas only. */
function splitInlineList(inner: string): string[] {
	const parts: string[] = [];
	let current = "";
	let quoted = false;
	let escaped = false;
	for (const ch of inner) {
		if (escaped) {
			current += ch;
			escaped = false;
			continue;
		}
		if (ch === "\\" && quoted) {
			current += ch;
			escaped = true;
			continue;
		}
		if (ch === '"') quoted = !quoted;
		if (ch === "," && !quoted) {
			parts.push(current);
			current = "";
		} else {
			current += ch;
		}
	}
	if (current.trim()) parts.push(current);
	return parts.map(p => p.trim()).filter(Boolean);
}

function parseScalar(raw: string): string | number | string[] {
	const value = raw.trim();
	if (value.startsWith("[") && value.endsWith("]")) {
		return splitInlineList(value.slice(1, -1)).map(item => {
			if (item.startsWith('"')) {
				try {
					return String(JSON.parse(item));
				} catch {
					return item.replace(/^"|"$/g, "");
				}
			}
			return item;
		});
	}
	if (/^-?\d+$/.test(value)) return Number(value);
	if (value.startsWith('"')) {
		try {
			return String(JSON.parse(value));
		} catch {
			return value.replace(/^"|"$/g, "");
		}
	}
	return value;
}

export function parsePage(path: string, raw: string): Page {
	const fallback: Page = { path, meta: { title: path, created: "", updated: "" }, body: raw };
	if (!raw.startsWith("---\n")) return fallback;
	const end = raw.indexOf("\n---", 4);
	if (end < 0) return fallback;
	const body = raw.slice(end + 4).replace(/^\s*\n/, "");
	const meta: Record<string, string | number | string[]> = {};
	const lines = raw.slice(4, end).split("\n");
	let arrayKey: string | undefined;
	for (const line of lines) {
		const blockItem = /^\s+-\s+(.*)$/.exec(line);
		if (blockItem && arrayKey) {
			const list = meta[arrayKey];
			if (Array.isArray(list)) list.push(parseScalar(blockItem[1]) as string);
			continue;
		}
		const kv = /^(\w+):\s*(.*)$/.exec(line);
		if (!kv) continue;
		const [, key, value] = kv;
		if (value === "") {
			// Possibly the head of a block-style array.
			meta[key] = [];
			arrayKey = key;
		} else {
			meta[key] = parseScalar(value);
			arrayKey = Array.isArray(meta[key]) ? undefined : undefined;
		}
	}
	const asString = (v: unknown): string => (typeof v === "string" ? v : v === undefined ? "" : String(v));
	return {
		path,
		meta: {
			title: asString(meta.title) || path,
			created: asString(meta.created),
			updated: asString(meta.updated),
			source: meta.source === undefined ? undefined : asString(meta.source),
			importance: typeof meta.importance === "number" ? meta.importance : undefined,
			tags: Array.isArray(meta.tags) ? (meta.tags as string[]).filter(t => typeof t === "string" && t) : undefined,
		},
		body,
	};
}

// ---------------------------------------------------------------------------
// Per-path write serialization. Handlers and tools can run concurrently
// across rebound sessions; this keeps same-page writes ordered.
// ---------------------------------------------------------------------------

const locks = new Map<string, Promise<unknown>>();

function withLock<T>(key: string, fn: () => Promise<T>): Promise<T> {
	const prev = locks.get(key) ?? Promise.resolve();
	const run = prev.catch(() => {}).then(fn);
	locks.set(
		key,
		run.catch(() => {}),
	);
	return run;
}

export interface UpsertTopicInput {
	/** Topic page slug; defaults to slugify(title). */
	slug?: string;
	title: string;
	body: string;
	source?: string;
	importance?: number;
	tags?: string[];
}

export interface UpsertTopicResult {
	path: string;
	created: boolean;
	/** True when new body content was appended to an existing page. */
	merged: boolean;
}

export class VaultStore {
	private readonly listeners = new Set<(relPath: string) => void>();

	private constructor(readonly root: string) {}

	static async open(root: string): Promise<VaultStore> {
		// resolve() normalizes separators — abs() escape checks compare with sep.
		const resolved = resolve(root);
		await mkdir(join(resolved, "topics"), { recursive: true });
		await mkdir(join(resolved, "daily"), { recursive: true });
		return new VaultStore(resolved);
	}

	/** Subscribe to write/delete notifications (used by the search index). */
	onChange(listener: (relPath: string) => void): void {
		this.listeners.add(listener);
	}

	private emit(relPath: string): void {
		for (const listener of this.listeners) {
			try {
				listener(relPath);
			} catch {
				// A broken listener must not break the write path.
			}
		}
	}

	private abs(rel: string): string {
		const p = resolve(this.root, rel);
		if (p !== this.root && !p.startsWith(this.root + sep)) {
			throw new Error(`path escapes vault root: ${rel}`);
		}
		return p;
	}

	async readPage(rel: string): Promise<Page | undefined> {
		let raw: string;
		try {
			raw = await readFile(this.abs(rel), "utf8");
		} catch (error) {
			if ((error as NodeJS.ErrnoException).code === "ENOENT") return undefined;
			throw error;
		}
		return parsePage(rel, raw);
	}

	private async writeUnlocked(rel: string, meta: PageMeta, body: string): Promise<void> {
		const target = this.abs(rel);
		await mkdir(dirname(target), { recursive: true });
		const tmp = `${target}.tmp-${process.pid}`;
		await writeFile(tmp, serializePage(meta, body), "utf8");
		await rename(tmp, target);
		this.emit(rel);
	}

	async writePage(rel: string, meta: PageMeta, body: string): Promise<void> {
		return withLock(rel, () => this.writeUnlocked(rel, meta, body));
	}

	async deletePage(rel: string): Promise<boolean> {
		return withLock(rel, async () => {
			try {
				await rm(this.abs(rel));
				this.emit(rel);
				return true;
			} catch (error) {
				if ((error as NodeJS.ErrnoException).code === "ENOENT") return false;
				throw error;
			}
		});
	}

	/**
	 * Append `text` to today's daily log under a `### HH:MM` heading,
	 * creating the page when missing. Returns the vault-relative path.
	 */
	async appendDaily(text: string, now: Date = new Date()): Promise<string> {
		const day = now.toISOString().slice(0, 10);
		const time = now.toISOString().slice(11, 16);
		const rel = `daily/${day}.md`;
		return withLock(rel, async () => {
			const existing = await this.readPage(rel);
			const iso = now.toISOString();
			if (!existing) {
				await this.writeUnlocked(
					rel,
					{ title: `Daily ${day}`, created: iso, updated: iso, source: "retain" },
					`# ${day}\n\n### ${time}\n${text.trim()}\n`,
				);
			} else {
				await this.writeUnlocked(
					rel,
					{ ...existing.meta, updated: iso },
					`${existing.body.trimEnd()}\n\n### ${time}\n${text.trim()}\n`,
				);
			}
			return rel;
		});
	}

	/**
	 * Create a topic page, or append a dated `## YYYY-MM-DD` section to an
	 * existing one. Identical content already present is skipped, so
	 * re-retaining the same fact does not grow the page.
	 */
	async upsertTopic(input: UpsertTopicInput, now: Date = new Date()): Promise<UpsertTopicResult> {
		const slug = input.slug ?? slugify(input.title);
		const rel = `topics/${slug}.md`;
		return withLock(rel, async () => {
			const iso = now.toISOString();
			const existing = await this.readPage(rel);
			if (!existing) {
				await this.writeUnlocked(
					rel,
					{
						title: input.title,
						created: iso,
						updated: iso,
						source: input.source,
						importance: input.importance,
						tags: input.tags?.length ? input.tags : undefined,
					},
					`# ${input.title}\n\n${input.body.trim()}\n`,
				);
				return { path: rel, created: true, merged: false };
			}
			if (existing.body.includes(input.body.trim())) {
				return { path: rel, created: false, merged: false };
			}
			const tags = [...new Set([...(existing.meta.tags ?? []), ...(input.tags ?? [])])];
			const importance = Math.max(existing.meta.importance ?? 0, input.importance ?? 0) || undefined;
			await this.writeUnlocked(
				rel,
				{ ...existing.meta, updated: iso, tags: tags.length ? tags : undefined, importance },
				`${existing.body.trimEnd()}\n\n## ${iso.slice(0, 10)}\n\n${input.body.trim()}\n`,
			);
			return { path: rel, created: false, merged: true };
		});
	}

	/** All vault-relative markdown paths, sorted; dotfiles skipped. */
	async listPages(): Promise<string[]> {
		const out: string[] = [];
		const walk = async (dir: string, prefix: string): Promise<void> => {
			let entries;
			try {
				entries = await readdir(dir, { withFileTypes: true });
			} catch (error) {
				if ((error as NodeJS.ErrnoException).code === "ENOENT") return;
				throw error;
			}
			for (const entry of entries) {
				if (entry.name.startsWith(".") || entry.name.endsWith(".tmp")) continue;
				const abs = join(dir, entry.name);
				const rel = prefix ? `${prefix}/${entry.name}` : entry.name;
				if (entry.isDirectory()) await walk(abs, rel);
				else if (entry.isFile() && entry.name.endsWith(".md")) out.push(rel);
			}
		};
		await walk(this.root, "");
		return out.sort();
	}
}
